"""
Bin-sorting policy, continuing from the current (un-reset) sim state.

What the trace shows:
  * The cube is NOT in the nominal spawn area: it is at about (0.20, 0.10),
    yaw about -41 deg, colour blue. Nothing here is hard-coded; cube and bin
    poses are read from the API. Cube xy readings jitter by several mm, so
    several reads are combined with a median.
  * Every time the old script descended below z ~ 0.09 over the cube, the TCP
    was pushed ~44 mm sideways (in the arm plane, away from the base) and
    stalled ~10 mm high. Suction was only tried after it had slid off, so it
    never gripped. Either the tool touches the cube much earlier than assumed,
    or the arm cannot physically get that low this close to its base.
  * move_to rejected the 'yaw' keyword. A top suction pick does not need yaw,
    so it is not passed at all.

Strategy: guarded descent in 4 mm steps, polling suction at every step from
well above the cube, and stopping as soon as the TCP stops tracking (if a TCP
getter exists). Verify the lift, carry high, lower the cube inside the bin
walls, release, check done(). Attempts are bounded. If the cube cannot be
gripped (e.g. it really is out of reach), the arm parks with suction off and
run() returns False instead of looping or raising.
"""

import math

SAFE_Z = 0.25
MAX_ATTEMPTS = 3

_TCP_GETTER = {"probed": False, "name": None}


# ----------------------------------------------------------------- helpers --
def _move_raw(api, xyz):
    xyz = [float(v) for v in xyz]
    try:
        return api.move_to(xyz)
    except TypeError:
        pass
    try:
        return api.move_to(xyz=xyz)
    except TypeError:
        pass
    return api.move_to(xyz, 0.0)


def _parse_xyz(v):
    try:
        if isinstance(v, dict):
            for k in ("xyz", "pos", "position", "tcp"):
                if k in v:
                    v = v[k]
                    break
        v = list(v)
        if len(v) and isinstance(v[0], (list, tuple)):
            v = list(v[0])
        if len(v) >= 3:
            out = [float(v[0]), float(v[1]), float(v[2])]
            if all(math.isfinite(c) for c in out):
                return out
    except Exception:
        pass
    return None


def _tcp(api):
    """Best-effort TCP read; returns None if the API has no such getter."""
    if not _TCP_GETTER["probed"]:
        _TCP_GETTER["probed"] = True
        for name in ("tcp_pose", "tcp", "get_tcp", "tcp_xyz", "ee_pose"):
            try:
                f = getattr(api, name, None)
                if f is None:
                    continue
                if _parse_xyz(f() if callable(f) else f) is not None:
                    _TCP_GETTER["name"] = name
                    break
            except Exception:
                continue
    name = _TCP_GETTER["name"]
    if name is None:
        return None
    try:
        f = getattr(api, name)
        return _parse_xyz(f() if callable(f) else f)
    except Exception:
        return None


def _goto(api, xyz, tol=0.004, retries=3):
    """Move, then re-issue the same target until the TCP has settled."""
    _move_raw(api, xyz)
    t = _tcp(api)
    if t is None:
        if retries > 1:
            _move_raw(api, xyz)  # no feedback: one extra call to let it settle
        return None
    n = 0
    while n < retries and math.dist(t, xyz) > tol:
        _move_raw(api, xyz)
        t = _tcp(api)
        if t is None:
            break
        n += 1
    return t


def _line(api, p0, p1, step=0.04):
    """Straight-line move in small steps (gentle on a held cube)."""
    d = math.dist(p0, p1)
    n = max(1, int(math.ceil(d / step)))
    for i in range(1, n + 1):
        a = i / n
        _move_raw(api, [p0[k] + a * (p1[k] - p0[k]) for k in range(3)])
    return _goto(api, p1)


def _median(vals):
    s = sorted(vals)
    return s[len(s) // 2]


def _sense_cube(api, n=5):
    xs, ys, zs, colour = [], [], [], None
    for _ in range(n):
        p = api.cube_pose()
        xs.append(float(p[0][0]))
        ys.append(float(p[0][1]))
        zs.append(float(p[0][2]))
        colour = p[2]
    return _median(xs), _median(ys), _median(zs), colour


def _sense_bin(api, colour, n=3):
    xs, ys, zs = [], [], []
    for _ in range(n):
        p = api.bin_pose(colour)
        xs.append(float(p[0][0]))
        ys.append(float(p[0][1]))
        zs.append(float(p[0][2]))
    return _median(xs), _median(ys), _median(zs)


def _suction(api, on):
    try:
        return bool(api.suction(on))
    except TypeError:
        return bool(api.suction(on=on))


def _retreat(api, x, y, z_from):
    z = z_from
    while z < SAFE_Z - 1e-6:
        z = min(SAFE_Z, z + 0.04)
        _move_raw(api, [x, y, z])
    _goto(api, [x, y, SAFE_Z])


# -------------------------------------------------------------------- pick --
def _try_pick(api, cx, cy, cz):
    """Guarded descent over the cube. Returns (held, grasp_z, last_cmd_z)."""
    _goto(api, [cx, cy, SAFE_Z])
    z = SAFE_Z
    z_start = cz + 0.10
    while z > z_start + 1e-6:
        z = max(z_start, z - 0.04)
        _move_raw(api, [cx, cy, z])
    _goto(api, [cx, cy, z_start])

    z = cz + 0.08
    z_min = cz - 0.002
    held = False
    grasp_z = z
    while z >= z_min - 1e-9:
        t = _goto(api, [cx, cy, z], tol=0.003, retries=1)
        held = _suction(api, True)
        if held:
            grasp_z = t[2] if t is not None else z
            break
        if t is not None:
            lateral = math.hypot(t[0] - cx, t[1] - cy)
            if lateral > 0.008 or (t[2] - z) > 0.009:
                # Blocked (contact or arm limit). Do not ram or slide off.
                # Back up slightly, re-centre and poll once more.
                zb = z + 0.006
                t2 = _goto(api, [cx, cy, zb], tol=0.003, retries=2)
                held = _suction(api, True)
                if held:
                    grasp_z = t2[2] if t2 is not None else zb
                    z = zb
                break
        z -= 0.004
    return held, grasp_z, max(z, z_min)


# --------------------------------------------------------------------- run --
def run(api):
    _suction(api, False)

    for _attempt in range(MAX_ATTEMPTS):
        if api.done():
            return True

        cx, cy, cz, colour = _sense_cube(api)
        bx, by, bz = _sense_bin(api, colour)

        held, grasp_z, last_z = _try_pick(api, cx, cy, cz)

        if not held:
            _suction(api, False)
            _retreat(api, cx, cy, last_z)
            continue

        # Lift straight up.
        z = last_z
        while z < SAFE_Z - 1e-6:
            z = min(SAFE_Z, z + 0.03)
            _move_raw(api, [cx, cy, z])
        _goto(api, [cx, cy, SAFE_Z])

        # Verify the cube actually came up with the tool.
        lifted = False
        try:
            p = api.cube_pose()
            lifted = float(p[0][2]) > cz + 0.05
        except Exception:
            pass
        if not lifted and not _suction(api, True):
            _suction(api, False)
            continue

        # Carry high to the bin and settle over its centre.
        _line(api, [cx, cy, SAFE_Z], [bx, by, SAFE_Z], step=0.05)
        _goto(api, [bx, by, SAFE_Z], tol=0.003, retries=4)

        # Lower until the cube is inside the walls, ~30 mm above the floor.
        h = (bz - 0.03) if 0.04 <= bz <= 0.20 else 0.03
        z_rel = grasp_z + h
        z = SAFE_Z
        while z > z_rel + 1e-6:
            z = max(z_rel, z - 0.03)
            _move_raw(api, [bx, by, z])
        _goto(api, [bx, by, z_rel], tol=0.003, retries=3)

        _suction(api, False)
        finished = False
        for _ in range(8):  # let the cube drop and settle
            if api.done():
                finished = True
                break

        _retreat(api, bx, by, z_rel)
        if finished or api.done():
            return True

    # Bounded failure: leave the cell safe instead of hammering the cube.
    _suction(api, False)
    if api.done():
        return True
    print("bin-sort: could not grip the cube after %d guarded attempts; "
          "it may be outside the arm's reachable pick zone." % MAX_ATTEMPTS)
    return False
